import * as SharedTypes from '@proma/shared'
import * as ElectronTypes from '../../../../types'
import { UPDATER_IPC_CHANNELS } from '../../updater/updater-types'

export type WebRemoteChannelLevel = 'read' | 'session' | 'workspace' | 'write' | 'confirm' | 'denied'
export type WebRemoteScope = 'none' | 'session' | 'workspace'

export interface WebRemoteChannelPolicyEntry { level: WebRemoteChannelLevel; scope: WebRemoteScope; rationale: string }

function channelValues(value: unknown): string[] {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return []
  return Object.values(value).filter((item): item is string => typeof item === 'string')
}

const EXPORTED_CHANNELS = new Set<string>([
  ...Object.entries(SharedTypes).filter(([name]) => name.endsWith('IPC_CHANNELS')).flatMap(([, value]) => channelValues(value)),
  ...Object.entries(ElectronTypes).filter(([name]) => name.endsWith('IPC_CHANNELS')).flatMap(([, value]) => channelValues(value)),
  ...channelValues(UPDATER_IPC_CHANNELS),
])

const RUNTIME_LITERAL_CHANNELS = new Set(['file:exists-batch', 'file:office-to-html', 'file:prepare-pdf-preview', 'file:read-binary-base64', 'file:resolve-and-read', 'file:resolve-html-preview-path', 'file:resolve-markdown-media', 'file:resolve-path', 'file:write-text', 'migration:open-data-folder', 'web-remote:admin-get', 'web-remote:admin-save', 'web-remote:admin-pair', 'web-remote:admin-revoke', 'web-remote:admin-push-test', 'web-remote:admin-push-delete'])

