export function getWebRemoteChannelPolicy(channel: string): WebRemoteChannelPolicyEntry | undefined { return WEB_REMOTE_CHANNEL_POLICY[channel] }

export function getDeclaredWebRemoteChannels(): string[] { return [...new Set([...EXPORTED_CHANNELS, ...RUNTIME_LITERAL_CHANNELS])].sort() }

export function policySummary(): Record<WebRemoteChannelLevel, number> {
  const summary: Record<WebRemoteChannelLevel, number> = { read: 0, session: 0, workspace: 0, write: 0, confirm: 0, denied: 0 }
  for (const entry of Object.values(WEB_REMOTE_CHANNEL_POLICY)) summary[entry.level]++
  return summary
}
